#!/usr/bin/env python3
from pathlib import Path
import json,gzip,copy
from shapely.geometry import shape,box
P=Path(__file__).resolve().parent;C=P.parent/'contexts'
with gzip.open(P/'source-objects.geojson.gz','rt',encoding='utf-8') as h:objects={f['id']:f for f in json.load(h)['features']}
r=json.load(open(P/'recipes.json'));tasks=json.load(open(P/'assignment.json'))['municipalities'];city={c['municipality']:c for c in tasks}
proposals={(f['properties']['municipality'],f['properties']['name']):f for f in json.load(open(P/'field-circuit-proposals.geojson'))['features']}
def get(c,kind,pred,scope=None):
 k=city[c]['contextKey'];fs=json.load(gzip.open(C/k/(kind+'.geojson.gz'),'rt'));out=[]
 for f in fs['features']:
  if not pred(f):continue
  if scope and not shape(f['geometry']).intersects(box(*scope)):continue
  f=copy.deepcopy(f);f['properties']['originalId']=f['id'];f['id']=k+':'+kind+':'+f['id'];objects[f['id']]=f;out.append(f['id'])
 return out
field_specs=[
 ('Csörötnek','Huszászi-part','https://www.honismeret.com/evfordulok2025/2005-os-ev','The local historical source identifies the Huszászi hillside/road locality. The inspected physical circuit follows actual hillside tracks and the Huszászi-patak channel, estimating a coherent lower-slope tract around the historical name rather than inventing a ring.','remaining-west-localities.json'),
 ('Balatonkeresztúr','Alsó-hegy','https://mdh.unideb.hu/telepules.php?adatlap=13-14-35&c=13-14-35&t=Balatonkereszt%C3%BAr','The academic Hungarian place-name database separately records Alsó-hegy. The inspected lower-hill circuit follows native vineyard/access tracks and the Sáros-gödör forest/field edges. It estimates the occupied lower hillside tract, preserving its irregular physical edges.','balaton-rural-search.json'),
 ('Balatonkeresztúr','Felső-hegy','https://mdh.unideb.hu/telepules.php?adatlap=13-14-35&c=13-14-35&t=Balatonkereszt%C3%BAr','The academic Hungarian place-name database separately records Felső-hegy. Its reviewed native uphill access-track and vineyard-edge circuit estimates the distinct upper-hill tract, north of the lower hill and Sáros-gödör.','balaton-rural-search.json'),
 ('Győr','Csikórét','https://www.openstreetmap.org/node/2206994158','The archived Csikórét name is on the floodplain field north of Malomsziget. The reviewed full field is physically enclosed by the actual Rába-bank/field track, the Holt-Marcal-side track and connecting native access tracks. This retains the large irregular meadow/field circuit, not the Malomsziget child footprint or a place-point ring.','gyor-cserszeg-street-lists.json'),
 ('Győr','Göcsei-földek','https://www.openstreetmap.org/node/2206994157','The archived Göcsei-földek name lies in a native mapped farmland block. Actual parcel edges and access tracks close the reviewed coherent field block. The original physical field is used as a source-based tract estimate rather than assigning an arbitrary broad urban parent.','gyor-cserszeg-street-lists.json'),
 ('Győr','Sörfőző-rét','https://www.openstreetmap.org/node/2206994172','The archived Sörfőző-rét name is in the floodplain west of Malomsziget. The reviewed meadow tract is closed by actual Holt-Marcal branches and native floodplain access tracks, including the wetland inside. The circuit is a physical landscape estimate, not a buffer or forced partition.','gyor-cserszeg-street-lists.json'),
 ('Ordacsehi','Bugaszeg','https://www.ordacsehi.hu/documents/4/4oroksegvedelemi_hatastanulmany.pdf','The municipal heritage study names Bugaszeg-puszta and its historic landscape. The inspected native access-track and woodland-edge circuit identifies a coherent field tract south of the M7 around the retained name. Archaeological/historical Bugaszeg can extend beyond this particular surviving field.','somogy-localities-search.json'),
 ('Balatonboglár','Botné','https://www.balatontipp.hu/balatoni_hirek/a-badacsonyi-borfajtak-jo-helyet-talaltak-a-regioban/','The retrieved local wine report explicitly names the Botné vineyard tract. A reviewed native circuit of hillside access tracks encloses the field around that retained geographic name. This is the actual irregular track-defined tract, not a rectangle centred on the point.','somogy-localities-search.json'),
 ('Magyaregres','Macska-liki-dűlő','https://www.openstreetmap.org/node/7672018703','The retained Macska-liki-dűlő name lies on the agricultural tract east of the village. The reviewed circuit follows actual field access tracks, the cemetery/farm edge and the Deseda stream-side corridor. It estimates a coherent northern field tract; the full historical dűlő limits are not published by these sources.','eastern-shard-search.json'),
 ('Balatonszárszó','Gönnye','https://www.openstreetmap.org/node/1280175920','The Gönnye name lies on the northern portion of a large native agricultural surface. A real interior field track and the original farmland/woodland edges close this reviewed distinct field tract southeast of road 7. It is not the identical whole farmland parent also containing Völgy-föld.','eastern-shard-search.json'),
 ('Balatonszárszó','Völgy-föld','https://www.openstreetmap.org/node/8904511469','The Völgy-föld name lies on the southwestern portion of a large native agricultural surface. Actual field access tracks, road-side/rail-side tracks and native farmland edges close a distinct reviewed tract. It is not assigned the identical whole farmland parent used by another name.','eastern-shard-search.json')]
for c,n,url,note,ev in field_specs:
 if any(x['municipality']==c and x['name']==n for x in r):continue
 f=proposals[c,n];ids=[]
 for s in f['properties']['boundarySources']:ids+=get(c,s['kind'],lambda f,id=s['id']:f['id']==id)
 t=next(t for t in city[c]['targets'] if t['name']==n);point=t['pointCandidates'][0]['coordinates'];url=t['pointCandidates'][0]['sourceUrl'] if url.startswith('https://www.openstreetmap.org/node/') else url
 mp=next(x['path'] for x in json.load(open(P/'review-map-index.json')) if x['city']==c and x['name']==n)
 r.append(dict(batch='batch-03',municipality=c,name=n,operation='physical-circuit',inputIds=ids,sourceNameAssociationPoint=point,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/'+ev,mp],partialFootprint=True,approximationNote=note+' The inspected source-road/stream/parcel circuit is physically closed without synthetic connector edges. The name point only associates an already source-defined tract with the name; it does not construct its shape. This remains an explicitly low-confidence partial tract/footprint estimate, because the complete historical/locality perimeter is not independently established.'))
def street(c,n,ns,url,note,ev,b=None,allow=40):
 if any(x['municipality']==c and x['name']==n for x in r):return
 ids=get(c,'roads',lambda f:f['properties']['name'] in ns,b);assert ids
 mun=json.load(open(C/city[c]['contextKey']/'municipality.geojson'))['features'][0]['geometry']
 r.append(dict(batch='batch-03',municipality=c,name=n,operation='street-envelope',inputIds=ids,inputScopes={i:b for i in ids} if b else {},clipGeometry=mun,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/'+ev],partialFootprint=False,frontageAllowanceM=allow,approximationNote=note+' Actual associated street segments define a whole occupied-quarter convex envelope, with an inferred '+str(allow)+' m outer plot/frontage allowance. Where recorded, coordinate scopes select local parts of long streets, not box-shaped output boundaries. Outer joins, historical limits and neighboring-quarter transitions remain low confidence; overlaps do not imply alias identity.'))
street('Balatonlelle','Felsőlelle',['Ady Endre utca','Állomás utca','Hársfa utca','Kossuth Lajos utca','Rákóczi út'],'https://utcak-magyarorszag.openalfa.com/fels%C5%91lelle','The actually opened named-quarter street inventory lists Ady, Állomás, Hársfa, Kossuth and Rákóczi. The local northern old-village street grid is estimated under its own Felsőlelle name; it is not copied to the neighboring names.','lelle-quarter-streets-tapolca.json',[17.6940,46.7838,17.7010,46.7890],35)
street('Balatonlelle','Kertalja',['Báthori utca','Dobó Katalin utca','Fenyő köz','Hársfa utca','Kossuth Lajos utca','Mátyás király utca','Petőfi Sándor utca','Sorház köz','Szövetség utca','Tabán köz','Tabán utca','Takács Sándor utca','Városháza tér'],'https://utcak-magyarorszag.openalfa.com/kertalja_balatonlelle','The actually opened Kertalja street inventory explicitly lists this central/southern old-village grid. Local portions of its long streets estimate the whole occupied Kertalja quarter, preserving a separately named overlapping extent.','lelle-quarter-streets-tapolca.json',[17.6930,46.7800,17.7050,46.7847],35)
street('Balatonlelle','Tabán',['Szent László utca','Tabán utca','Tabán köz','Sorház köz'],'https://utcak-magyarorszag.openalfa.com/taban_balatonlelle','The actually opened Tabán inventory associates Szent László and Tabán streets with the name, while the archived local-map evidence locates the connected Sorház/Tabán close. Their real grid estimates the smaller southern quarter rather than a duplicated Felsőlelle/Kertalja surface.','lelle-quarter-streets-tapolca.json',allow=35)
street('Tapolca','Keleti városrész',['Barackvirág utca','Bem apó utca','Bertha Vince utca','Berzsenyi Dániel utca','Bolyai János utca','Egry József utca','Juhász Gyula utca','Kazinczy tér','Keresztury Dezső utca','Kodály Zoltán utca','Lóczy Lajos utca','Móricz Zsigmond utca','Simon István utca'],'https://njt.jog.gov.hu/jogszabaly/2015-24-SP-5Y3858','Municipal legislation identifies the eastern-quarter centre at Berzsenyi street. The archived named-quarter street inventory supplies the surrounding complete actual eastern residential grid, including Kazinczy and the northern/eastern streets. This estimates the broader whole quarter, not only the Y-house child estate.','tapolca-quarter-streets.json',[17.4420,46.8800,17.4610,46.8920],40)
(P/'recipes.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');(P/'source-objects.geojson.gz').write_bytes(gzip.compress(json.dumps(dict(type='FeatureCollection',features=list(objects.values())),ensure_ascii=False,separators=(',',':')).encode(),mtime=0));print(len(r),'recipes')
